import {upgradePersonalHome,residentLinks} from './personal-home.mjs';
import {spotSpace} from './spaces.mjs';
import {assetURL} from './asset-url.mjs';
import {LayoutEditor} from './editor.mjs';
import {Room,spots} from './room.mjs';
import {normalizeHome,validBackup,portableBackup,enforceSingleObject,bindStory,placeStory,upgradeStories,seedPondExamples,detachSource} from './home-data.mjs';
import {extractPalette} from './photo-palette.mjs';
import {visibleObject} from './furnishing-data.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formNames={card:'小卡片',frame:'木相框',lamp:'叠色小灯',clay:'黏土小物',fish:'流彩小鱼',box:'搬家纸箱',tote:'帆布袋',rabbit:'旧兔子'},symbols={card:'▱',frame:'▣',lamp:'☼',clay:'◒',fish:'✧',box:'□',tote:'♧',rabbit:'♧'};
const today=()=>new Date().toLocaleDateString('sv-SE');let layout={},bindings={},editor;let db,records=[],room,pending=null,currentSpot='table',timer,night=false,audio=null,playing=false,sequence=Promise.resolve();
const examples=()=>[{id:'metro',title:'车窗里叠着另一个自己',note:'昏黄的地铁灯光，橙绿的座位。那一下奇异的感觉，想把它留住。',date:'2026-09-06',form:'lamp',palette:['#c99465','#879f85','#e9cf91'],spot:'window',rotation:0,scale:1,parents:[],example:true},{id:'sunset',title:'晚霞的一小块',note:'粉色慢慢退下去，蓝灰色的天还亮着。',date:'2026-08-28',form:'clay',palette:['#d2a49a','#91a9ba','#d8b671'],spot:'cabinet',rotation:0,scale:1,parents:[],example:true},{id:'note',title:'不必把每一天都填满',note:'今天没有发生什么大事，只是坐了一会儿。这样也很好。',date:'2026-09-02',form:'card',palette:['#a3b097','#d6c3a4','#e6cc9d'],spot:'side',rotation:-.15,scale:1,parents:[],example:true}];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function open(title,kicker,html){$('#object-hint').hidden=true;$('#panel-title').textContent=title;$('#panel-kicker').textContent=kicker;$('#content').innerHTML=html;if(!$('#panel').open)$('#panel').showModal();}
function close(){$('#panel').close();}
async function writeHome(next){await new Promise((resolve,reject)=>{const tx=db.transaction('home','readwrite'),store=tx.objectStore('home');store.put(next.records,'memories');store.put(next.layout,'layout');store.put(next.bindings,'storyBindings');store.put(2,'storyEdition');store.put(2,'gardenVersion');store.put(1,'pondEdition');store.put(1,'personalEdition');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function initDB(){
 db=await new Promise((resolve,reject)=>{const q=indexedDB.open('memory-nook-v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('home');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
 const read=key=>new Promise((resolve,reject)=>{const q=db.transaction('home').objectStore('home').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});
 const [saved,oldLayout,oldBindings,edition,gardenVersion,pondEdition,personalEdition]=await Promise.all(['memories','layout','storyBindings','storyEdition','gardenVersion','pondEdition','personalEdition'].map(read));
 const next=normalizeHome(upgradeStories({records:saved||examples(),layout:oldLayout||{},bindings:oldBindings||{},gardenVersion},edition),{seedStories:edition===undefined});
 if(pondEdition===undefined)seedPondExamples(next);
 upgradePersonalHome(next,personalEdition);enforceSingleObject(next);
 await writeHome(next);records=next.records;layout=next.layout;bindings=next.bindings;
}
function changeHome(fn){const task=sequence.then(async()=>{const next=structuredClone({records,layout,bindings});fn(next);enforceSingleObject(next);await writeHome(next);records=next.records;layout=next.layout;bindings=next.bindings;refresh();return true;}).catch(()=>{toast('没有保存成功，请导出备份后重试。');return false;});sequence=task.then(()=>{});return task;}
function change(fn){return changeHome(next=>fn(next.records));}
function refresh(){if(editor)editor.records=records;const sample=records.some(r=>r.personalEdition&&(r.spot||attached(r.id).length));if(room?.space!=='courtyard')document.querySelector('.room-label').textContent=sample?'01 / 阿禾的小屋 · 虚构示例':'01 / 我的记忆小屋';$('#count').textContent=records.filter(r=>!r.retiredExample).length;room?.setRecords(records);room?.stories.apply(records,bindings);}
function propName(id){return room?.stories.objects.get(id)?.userData.movable||'小物件';}
function attached(id){return Object.entries(bindings).filter(([,source])=>source===id);}
function sourcePlaces(r){const parts=[(r.spot==='pond'?'院子池塘':spots.find(s=>s.id===r.spot)?.name),...attached(r.id).filter(([id])=>{const o=room?.stories.objects.get(id);return !o||visibleObject(o);}).map(([id])=>propName(id))].filter(Boolean);return [...new Set(parts)].join(' · ')||'收在记忆匣';}
function creditHTML(r){if(r.generatedImage)return '<p class="photo-credit">虚构住户的生活快照 · AI 生成示例</p>';return r.photoCredit?`<p class="photo-credit">示例影像 · 摄影 <a href="${esc(r.photoCredit.url)}" target="_blank" rel="noopener noreferrer">${esc(r.photoCredit.creator)}</a> / Unsplash</p>`:'';}
function relocateProp(id){close();const targetSpace=id.startsWith('courtyard/')?'courtyard':'living-room';if(room?.space!==targetSpace)switchSpace(targetSpace);editor?.setEnabled(true);editor?.select(room?.stories.objects.get(id));}
function propDetail(id){const source=bindings[id];if(records.some(r=>r.id===source)){detail(source,id);return;}open(propName(id),'A PLACE FOR YOUR STORY',`<p class="quote">这个小东西，还可以留下一段你的故事。</p><div class="row"><button class="primary" id="choose-story">放进一段记忆</button><button id="move-prop">挪个位置</button></div>`);$('#choose-story').onclick=()=>chooseStory(id);$('#move-prop').onclick=()=>relocateProp(id);}
function chooseStory(propId){const ordered=[...records].sort((a,b)=>Number(!!a.example)-Number(!!b.example)||b.date.localeCompare(a.date));open('把哪段记忆留在这里？',propName(propId),`<div class="row"><button class="primary" id="new-prop-story">＋ 留下新的照片与故事</button></div><p class="note">照片里的颜色会轻轻落在这件物品上。一张照片只留在一件物品里。选中已经安放的记忆，会把它从原物件移到这里。</p>${ordered.map(r=>`<button class="memory" data-bind="${r.id}">${r.image?`<img src="${esc(assetURL(r.image))}" alt="">`:'<span class="icon">✧</span>'}<span><b>${esc(r.title)}</b><small>${r.example?'示例 · ':''}${esc(r.date)} · ${esc(sourcePlaces(r))}</small></span></button>`).join('')}`);$('#new-prop-story').onclick=()=>keep(propId);document.querySelectorAll('[data-bind]').forEach(b=>b.onclick=async()=>{if(await changeHome(next=>bindStory(next,propId,b.dataset.bind))){propDetail(propId);toast('这段记忆，安放在这里了。');}});}
function paletteHTML(r){return '<div class="palette">'+r.palette.map(c=>`<span style="background:${c}"></span>`).join('')+'</div>';}
function detail(id,propId=null){
 const r=records.find(x=>x.id===id);if(!r)return;const prop=propId&&room?.stories.objects.get(propId),colors=prop?.userData.displayPalette;
 open(r.title,propId?propName(propId)+' · 留在这里的故事':'A LITTLE PIECE OF YOUR LIFE',`${r.image?`<img class="photo" src="${esc(assetURL(r.image))}" alt="${esc(r.title)}的来源照片">${creditHTML(r)}`:paletteHTML(r)}<div class="meta">${r.example?'示例记忆 · ':''}${esc(r.date)} · ${esc(propId?propName(propId):sourcePlaces(r))}</div><p class="quote">${esc(r.note||'这一刻，留在这里。')}</p>${r.personalEdition?`<div class="trace-links"><span>阿禾的小屋 · 虚构生活示例</span>${(residentLinks[r.id]||[]).filter(id=>records.some(x=>x.id===id&&x.personalEdition)).map(id=>`<button class="text-button" data-nearby="${id}">${esc(records.find(x=>x.id===id).title)} →</button>`).join('')}</div>`:''}${colors&&r.image?`<details class="color-story"><summary>照片里的颜色，留在小屋里</summary><div class="color-pair"><span>照片采色${paletteHTML(r)}</span><span>柔和后的配色${paletteHTML({palette:colors})}</span></div><p class="note">保留照片的颜色线索，调整明暗与饱和度，让它和家里的木头、布料相处。</p></details>`:''}${!propId&&attached(id).length?`<div class="trace-links"><span>安放在这里</span>${attached(id).filter(([key])=>{const o=room?.stories.objects.get(key);return o&&visibleObject(o);}).map(([key])=>`<button class="text-button" data-prop="${key}">${esc(propName(key))}</button>`).join('')}</div>`:''}${r.parents?.length?`<p class="note">来自两段记忆：</p>${r.parents.map(p=>{const source=records.find(x=>x.id===p);return `<button class="text-button" data-source="${p}">${esc(source?.title||'来源已移除')}</button>`}).join('')}`:''}<div class="row"><button class="primary" id="relocate">${propId?'挪动这件物品':'找个新位置'}</button><button id="reshape">${propId?'换成我的记忆':'换一种模样'}</button></div><div class="row"><button id="edit" class="text-button">编辑照片与故事</button><button id="connect" class="text-button">与另一段记忆相遇</button></div><div class="row"><button id="put-away" class="text-button">${propId?'取下这个故事':'收进记忆匣'}</button><button id="remove" class="text-button">删除这段记忆</button></div>`);
 document.querySelectorAll('[data-nearby]').forEach(b=>b.onclick=()=>detail(b.dataset.nearby,attached(b.dataset.nearby)[0]?.[0]));
 $('#relocate').onclick=()=>propId?relocateProp(propId):attached(id).length?relocateProp(attached(id)[0][0]):place(r);$('#reshape').onclick=()=>propId?chooseStory(propId):shape(r);$('#edit').onclick=()=>edit(r,propId);
 $('#put-away').onclick=async()=>{if(await changeHome(next=>{if(propId)delete next.bindings[propId];else{next.records.find(x=>x.id===id).spot=null;for(const key of Object.keys(next.bindings))if(next.bindings[key]===id)delete next.bindings[key];}})){close();toast('故事收好了，随时可以再放回来。');}};
 $('#remove').onclick=()=>{open('真的要移除这个片刻吗？','REMOVE A MEMORY','<p class="note">原照片、笔记和物件上的故事关联会一起删除，家具本身仍然保留。这个操作无法撤回。</p><div class="row"><button id="keep-it">留下它</button><button id="delete-it">确认删除</button></div>');$('#keep-it').onclick=()=>detail(id,propId);$('#delete-it').onclick=async()=>{if(records.some(x=>x.parents?.includes(id))){toast('它仍是另一件纪念物的来源，请先移除那件作品。');return;}if(await changeHome(next=>{next.records.splice(next.records.findIndex(x=>x.id===id),1);for(const key of Object.keys(next.bindings))if(next.bindings[key]===id)delete next.bindings[key];})){close();}};};
 $('#connect').onclick=()=>connect(r);document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>detail(b.dataset.source));document.querySelectorAll('[data-prop]').forEach(b=>b.onclick=()=>propDetail(b.dataset.prop));
}
function boxView(query=''){const list=records.filter(r=>!r.retiredExample&&(r.title+' '+r.note).includes(query)).sort((a,b)=>b.date.localeCompare(a.date));open('你的记忆匣','EVERYTHING YOU CHOSE TO KEEP',`<p class="note">${records.filter(r=>!r.spot&&!attached(r.id).length).length} 个片刻收在匣子里。书和抱枕上的故事，也都能在这里找回。</p><input id="search" aria-label="搜索记忆" placeholder="找一句话，或一段记忆" value="${esc(query)}"><div>${list.map(r=>`<button class="memory" data-id="${r.id}">${r.image?`<img src="${esc(assetURL(r.image))}" alt="">`:`<span class="icon">${symbols[r.form]}</span>`}<span><b>${esc(r.title)}</b><small>${esc(r.date)} · ${esc(sourcePlaces(r))}${r.example?' · 示例':''}</small></span></button>`).join('')||'<p class="note">这里还没有那个片刻。</p>'}</div>`);$('#search').onchange=e=>boxView(e.target.value);document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));}
async function imageData(file){if(file.size>8*1024*1024)throw Error('照片请小于 8 MB');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP');const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=data;});const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,32,32);const pixels=ctx.getImageData(0,0,32,32).data;return{image:data,palette:extractPalette(pixels),paletteMethod:'sampled'};}
function keep(propId=null){open('今天，想留下什么？','KEEP A LITTLE MOMENT',`<p class="note">${propId?'把照片和故事留在'+esc(propName(propId))+'里。':'先留下，等有空时再慢慢安放。'}</p><label class="field">一张照片（可选）</label><input id="photo" type="file" accept="image/jpeg,image/png,image/webp"><label class="field">一句话也可以</label><textarea id="note" maxlength="1000" placeholder="窗外的光刚刚变成了一种很奇怪的橙色……"></textarea><label class="field">片刻的日期</label><input id="date" type="date" value="${today()}"><div class="row"><button id="quick">先收好</button><button class="primary" id="shape-now">${propId?'留在这件物品上':'选一个模样 →'}</button></div><p class="subtle">保存在当前浏览器 · 照片不上传</p>`);const save=async(next)=>{const note=$('#note').value.trim(),file=$('#photo').files[0],date=$('#date').value;if(!note&&!file){toast('写几个字，或选一张照片。');return;}if(!date){toast('请选择日期');return;}const buttons=[$('#quick'),$('#shape-now')];buttons.forEach(b=>b.disabled=true);try{const media=file?await imageData(file):{image:null,palette:['#cfaa86','#9bacaa','#d8c48d']};const r={id:crypto.randomUUID(),title:note.slice(0,16)||'一个新片刻',note,date,...media,form:'card',spot:null,rotation:0,scale:1,parents:[]};if(await changeHome(home=>{home.records.push(r);if(propId&&next)bindStory(home,propId,r.id);})){if(propId&&next){propDetail(propId);toast('照片的颜色和故事，都留下来了。');}else if(next)shape(r);else{close();toast('收好了，回家再慢慢安放。');}}}catch(e){toast(e.message||'照片读取失败');}finally{buttons.forEach(b=>b.disabled=false);}};$('#quick').onclick=()=>save(false);$('#shape-now').onclick=()=>save(true);}
function shape(r){let form=r.form;open('让它以什么模样留下？','GIVE YOUR MEMORY A FORM',`<p class="note">保留原来的样子，或把它变成桌上的小东西。</p><div class="options">${Object.entries(formNames).map(([k,v])=>`<button class="option ${form===k?'active':''}" data-form="${k}"><span class="symbol">${symbols[k]}</span><strong>${v}</strong><small>${{card:'原照片与一句话',frame:'放进一个木头小框',lamp:'让颜色变成暖光',clay:'把颜色捏成一片风景',fish:'让这个片刻游进池塘'}[k]}</small></button>`).join('')}</div>${paletteHTML(r)}<label class="field">给它一个名字</label><input id="name" maxlength="80" value="${esc(r.title)}"><div class="row"><button id="later">先收进匣子</button><button class="primary" id="bring">带它回家 →</button></div><p class="note">摆件使用手作模板与照片采色；当前没有接入 AI 建模。</p>`);document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{form=b.dataset.form;document.querySelectorAll('[data-form]').forEach(b=>b.classList.toggle('active',b.dataset.form===form));});const save=async(doPlace)=>{const title=$('#name').value.trim()||r.title;if(await changeHome(home=>{Object.assign(home.records.find(x=>x.id===r.id),{form,title});if(form==='fish'&&home.records.find(x=>x.id===r.id).spot!=='pond'||form!=='fish'&&home.records.find(x=>x.id===r.id).spot==='pond')detachSource(home,r.id);if(!doPlace)detachSource(home,r.id);})){if(doPlace)place(records.find(x=>x.id===r.id));else{close();toast('留在记忆匣里了。');}}};$('#later').onclick=()=>save(false);$('#bring').onclick=()=>save(true);}
async function place(r){editor?.setEnabled(false);if(r.form==='fish'){if(await changeHome(home=>placeStory(home,r.id,{spot:'pond',position:null,parentId:null,localPosition:null,rotation:0}))){close();switchSpace('courtyard');toast('这个片刻，开始在池塘里游动了。');}return;}if(!room){toast('三维画面暂不可用，记忆已保存在匣子。');return;}close();pending=structuredClone(r);currentSpot=spotSpace(r.spot)===room.space&&r.spot?r.spot:room.space==='courtyard'?'garden-table':'table';room.setRecords(records.filter(x=>x.id!==r.id));room.startPlace(pending,currentSpot);document.body.classList.add('placing');$('#placement').hidden=false;renderSpots();}
function renderSpots(){$('#spots').innerHTML=spots.filter(s=>spotSpace(s.id)===room.space).map(s=>`<button data-spot="${s.id}" class="${currentSpot===s.id?'active':''}">${s.name}</button>`).join('');document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>pickSpot(b.dataset.spot));}
function pickSpot(id){if(!pending)return;currentSpot=id;room.movePreview(id);renderSpots();}
function stopPlace(){room?.stopPlace();pending=null;$('#placement').hidden=true;document.body.classList.remove('placing');refresh();}
$('#confirm-place').onclick=async()=>{if(!pending)return;const p=pending;if(records.filter(r=>r.spot===currentSpot&&r.id!==p.id).length>=3){toast('这个角落有些满了，换个位置吧。');return;}if(await changeHome(home=>placeStory(home,p.id,{spot:currentSpot,rotation:p.rotation,position:null,localPosition:null,parentId:null}))){stopPlace();toast('找到它的小位置了。');$('#observation').textContent='「'+p.title+'」也回家了。';}};$('#cancel-place').onclick=stopPlace;$('#rotate-place').onclick=()=>{if(pending){pending.rotation=(pending.rotation||0)+Math.PI/4;room.preview.rotation.y=pending.rotation;}};document.addEventListener('keydown',e=>{if(!pending)return;if(e.key==='Escape')stopPlace();if(e.key.toLowerCase()==='r')$('#rotate-place').click();});
function edit(r,propId=null){open('补上一点故事','A NOTE TO YOUR FUTURE SELF',`<label class="field">名字</label><input id="edit-title" maxlength="80" value="${esc(r.title)}"><label class="field">笔记</label><textarea id="edit-note" maxlength="1000">${esc(r.note)}</textarea><label class="field">换一张照片（可选）</label><input id="edit-photo" type="file" accept="image/jpeg,image/png,image/webp"><p class="note">更换原照片后，这件物品会重新取色。一张照片只对应一件物品。</p><label class="field">日期</label><input id="edit-date" type="date" value="${esc(r.date)}"><div class="row"><button class="primary" id="save-edit">留好这段故事</button></div>`);$('#save-edit').onclick=async()=>{const title=$('#edit-title').value.trim()||r.title,note=$('#edit-note').value,date=$('#edit-date').value,file=$('#edit-photo').files[0],button=$('#save-edit');if(!date)return;button.disabled=true;try{const media=file?{...await imageData(file),example:false,photoCredit:null,generatedImage:false}:{};if(media.image&&records.some(x=>x.id!==r.id&&x.image===media.image&&(x.spot||attached(x.id).length)))throw Error('这张照片已经有自己的物件，请选择另一张，或从记忆匣移动原来的物件。');if(await change(rs=>Object.assign(rs.find(x=>x.id===r.id),{title,note,date,example:false,personalEdition:null,resident:null,...media})))detail(r.id,propId);}catch(e){toast(e.message||'照片读取失败');}finally{button.disabled=false;}};}
function connect(a){const candidates=records.filter(r=>r.id!==a.id);open('让两个片刻相遇','FROM TWO DIFFERENT DAYS',`<p class="note">把「${esc(a.title)}」的颜色，和另一段记忆一起做成一盏小灯。两份原记录会完整保留。</p>${candidates.map(r=>`<button class="memory" data-pair="${r.id}"><span class="icon">${symbols[r.form]}</span><span><b>${esc(r.title)}</b><small>${esc(r.date)}</small></span></button>`).join('')||'<p class="note">再留下一段记忆，就能让它们相遇。</p>'}`);document.querySelectorAll('[data-pair]').forEach(b=>b.onclick=async()=>{const other=records.find(r=>r.id===b.dataset.pair);const child={id:crypto.randomUUID(),title:'两天之间的一盏灯',note:'来自「'+a.title+'」与「'+other.title+'」。',date:today(),palette:[a.palette[0],other.palette[1],other.palette[2]],form:'lamp',spot:null,rotation:0,scale:1,parents:[a.id,other.id]};if(await change(rs=>rs.push(child)))shape(child);});}
async function download(){try{await sequence;const data=await portableBackup({records,layout,bindings},async path=>{const response=await fetch(assetURL(path));if(!response.ok)throw Error('示例照片未能打包，请稍后重试');const blob=await response.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});});const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='memory-nook-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('照片、故事、布局和关联一起打包好了。');}catch(e){toast(e.message||'备份未能导出，请重试。');}}
function settings(){open('把这个家好好留住','YOUR PRIVATE NOOK',`<p class="note">记忆保存在当前浏览器。导出备份可以带走原照片、笔记、摆放位置，以及家具上的故事关联。</p><div class="row"><button class="primary" id="export">导出完整备份</button></div><label class="field">从备份恢复</label><input id="import" type="file" accept="application/json"><p class="note">恢复会替换当前记忆，请先导出备份。</p><div class="row"><button id="clear-samples">收起示例纪念物</button></div><p class="note">童话小屋原型 · 三维家具与摆件使用模块化几何。音乐为本机合成的简短旋律。当前没有在线 AI 服务。</p>`);$('#export').onclick=download;$('#clear-samples').onclick=async()=>{if(await changeHome(next=>{next.records.forEach(r=>{if(r.example)r.spot=null;});for(const key of Object.keys(next.bindings))if(next.records.find(r=>r.id===next.bindings[key])?.example)delete next.bindings[key];})){close();toast('示例收进匣子，房间留给你。');}};$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100*1024*1024)throw Error();const data=JSON.parse(await f.text());if(!validBackup(data))throw Error();open('用备份里的记忆替换当前内容？','RESTORE YOUR NOOK',`<p class="note">将恢复 ${data.records.length} 段记忆。当前内容将被替换。</p><div class="row"><button id="abort">取消</button><button id="restore" class="primary">确认恢复</button></div>`);$('#abort').onclick=settings;$('#restore').onclick=async()=>{const restored=normalizeHome(data);if(await changeHome(next=>Object.assign(next,restored))){editor?.apply(layout);refresh();close();toast('记忆和它们的位置，一起回来了。');}};}catch{toast('这不是可读取的记忆小屋备份。');}};}
function music(){if(!audio){const AC=window.AudioContext||window.webkitAudioContext;audio=new AC();}playing=!playing;if(playing){audio.resume();const play=()=>{if(!playing)return;const notes=[261.63,329.63,392,493.88,440,392,329.63,293.66];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.8;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.026,t+.04);g.gain.exponentialRampToValueAtTime(.0001,t+2.4);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+2.5);});};play();audio.loop=setInterval(play,9000);}else{clearInterval(audio.loop);audio.suspend();}$('#music').textContent=playing?'♫ 音乐开':'♫ 音乐关';}
$('#add').onclick=()=>keep();$('#box').onclick=()=>boxView();$('#settings').onclick=settings;$('#close').onclick=close;$('#home').onclick=e=>{e.preventDefault();close();if(room){room.angle=.78;room.zoom=1;room.resize();}};$('#left').onclick=()=>room?.rotate(-.15);$('#right').onclick=()=>room?.rotate(.15);$('#reset').onclick=()=>$('#home').click();$('#zoom-in').onclick=()=>{if(room){room.zoom=Math.min(1.45,room.zoom+.1);room.resize();}};$('#zoom-out').onclick=()=>{if(room){room.zoom=Math.max(.7,room.zoom-.1);room.resize();}};$('#day').onclick=()=>{night=!night;room?.night(night);$('#day').textContent=night?'☾ 黄昏':'☀ 午后';};$('#music').onclick=music;
try{await initDB();try{room=new Room($('#scene'),detail,pickSpot);room.onPropPick=propDetail;editor=new LayoutEditor(room,layout,saveLayout,async(id,t)=>{await change(rs=>Object.assign(rs.find(r=>r.id===id),t));});}catch(e){$('#scene').innerHTML='<div class="error">三维房间暂时没有打开。<p>仍然可以在记忆匣里保存和回看。</p></div>';console.error(e);}refresh();}catch(e){$('#add').disabled=true;toast('浏览器存储无法打开，请允许网站使用本地存储。');}
function saveLayout(next){return changeHome(home=>home.layout=next);}
$('#arrange').onclick=()=>editor?.setEnabled(!editor.enabled);$('#turn-object').onclick=()=>editor?.rotate(Math.PI/8);$('#object-height').onchange=e=>editor?.height(e.target.value);$('#reset-object').onclick=()=>editor?.resetSelected();

function switchSpace(space){if(!room)return;if(pending)stopPlace();room.switchSpace(space);document.body.dataset.space=space;$('#space-exit').textContent=space==='courtyard'?'回窗边小屋':'去花园与池塘';$('#space-exit').setAttribute('aria-label',space==='courtyard'?'回窗边小屋':'去花园与池塘');document.querySelector('.welcome h1').textContent=space==='courtyard'?'在这里，慢一点。':'回来就好。';document.querySelector('.room-label').textContent=space==='courtyard'?'02 / 有水声的小院':'01 / 阿禾的小屋 · 虚构示例';$('#observation').innerHTML=space==='courtyard'?'轻触水面，等一个片刻游近。<small>点小鱼，重新遇见它的故事。</small>':'杯子带来了，旧抱枕也带来了。<small>点一件小东西，慢慢认识住在这里的人。</small>';}
$('#space-exit').onclick=()=>switchSpace(room?.space==='courtyard'?'living-room':'courtyard');
if(room)room.onWater=p=>{const id=room.pond.tap(p.x,p.z);if(!id)toast('池塘还没有记忆鱼。在记忆匣中选一个片刻，换成「流彩小鱼」吧。');};

$('#pond-invite').onclick=()=>{open('让哪个片刻游进池塘？','A MEMORY THAT LEARNS TO SWIM',`<p class="note">它会从原来的物件移到池塘。原照片、笔记和日期都会留着。</p>${records.map(r=>`<button class="memory" data-swim="${r.id}">${r.image?`<img src="${esc(assetURL(r.image))}" alt="">`:'<span class="icon">✧</span>'}<span><b>${esc(r.title)}</b><small>${esc(sourcePlaces(r))}</small></span></button>`).join('')||'<p class="note">先用「留下一个片刻」收好一段记忆吧。</p>'}`);document.querySelectorAll('[data-swim]').forEach(b=>b.onclick=async()=>{const id=b.dataset.swim;if(await changeHome(home=>{const r=home.records.find(r=>r.id===id);r.form='fish';placeStory(home,id,{spot:'pond',position:null,localPosition:null,parentId:null,rotation:0});})){close();toast('轻触水面，等它游近。');}});};

if(room)room.onNavigate=switchSpace;
